def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width and full-height uniform lines divide the grid into tiles.
    row_cuts = [r for r in range(h) if len(set(grid[r])) == 1]
    col_cuts = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1]

    def groups(size, cuts):
        result = []
        start = 0
        for cut in cuts:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        if start < size:
            result.append((start, size))
        return result

    rows = groups(h, row_cuts)
    cols = groups(w, col_cuts)

    # The marker is the non-background color appearing sparsely inside tiles.
    counts = {}
    for r0, r1 in rows:
        for c0, c1 in cols:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    background = max(counts, key=counts.get)

    return [
        [2 if sum(grid[r][c] != background
                  for r in range(r0, r1)
                  for c in range(c0, c1)) == 1 else 1
         for c0, c1 in cols]
        for r0, r1 in rows
    ]
